    /// A line the run printed, every path in it from its container mapped
    /// back to the host, so whatever reads it sees host paths.
    pub fn map_line(&self, line: &str) -> String {
        if self.platform.same_paths() {
            return line.to_string();
        }
        // JSON escapes a Windows path's separators.
        let host = self.project_dir.to_string_lossy().replace('\\', "\\\\");
        line.replace(WORKSPACE, &host)
    }

    /// The volume holding the harness's sessions for this run's
    /// conversation in its project.
    pub fn session_volume(&self) -> String {
        session_volume(&self.project_dir, self.kind)
    }

    /// The arguments to `podman` that run `command` with `args` in a
    /// container of `image` as this plan says, its input open; with `tty`,
    /// under a terminal of its own.
    pub fn run_args(
        &self,
        image: &str,
        command: &str,
        args: &[OsString],
        tty: bool,
    ) -> Vec<OsString> {
        let mut out: Vec<OsString> = vec!["run".into(), "--rm".into(), "-i".into()];
        if tty {
            out.push("-t".into());
        }
        // Files it writes belong to the user, as on the host.
        if self.platform == Platform::Linux {
            out.push("--userns=keep-id".into());
        }
        out.extend(["--label".into(), "suspense=run".into()]);
        out.extend(["-e".into(), format!("HOME={HOME}").into()]);
        // The harness's login and settings, shared by every project, and the
        // sessions of this conversation in this project over them.
        out.extend([
            "-v".into(),
            format!("{}:{HOME}:U", home_volume(self.agent)).into(),
        ]);
        out.extend([
            "-v".into(),
            format!(
                "{}:{HOME}/{}:U",
                self.session_volume(),
                session_dir(self.agent)
            )
            .into(),
        ]);
        if self.kind == RunKind::Code {
            out.extend([
                "-v".into(),
                format!("{}:{CACHE}:U", cache_volume(&self.project_dir)).into(),
            ]);
            out.extend(["-e".into(), format!("CARGO_HOME={CACHE}/cargo").into()]);
            out.extend([
                "-e".into(),
                format!("CARGO_TARGET_DIR={CACHE}/target").into(),
            ]);
        }
        for mount in &self.mounts {
            let mut spec: OsString = "type=bind,src=".into();
            spec.push(mount.host.as_os_str());
            spec.push(",dst=");
            spec.push(self.container_path(&mount.host).as_os_str());
            if !mount.writable {
                spec.push(",ro=true");
            }
            out.extend(["--mount".into(), spec]);
        }
        for hidden in &self.hidden {
            let mut spec: OsString = "type=tmpfs,dst=".into();
            spec.push(self.container_path(hidden).as_os_str());
            spec.push(",ro=true");
            out.extend(["--mount".into(), spec]);
        }
        out.push("-w".into());
        out.push(self.container_path(&self.project_dir).into_os_string());
        out.push(image.into());
        out.push(command.into());
        out.extend(args.iter().cloned());
        out
    }
}

/// The volume a harness keeps its login and settings in, shared by every
/// project.
pub fn home_volume(agent: Agent) -> String {
    format!("suspense-home-{}", agent.command())
}

/// The volume a harness keeps the sessions of a project's conversation in.
pub fn session_volume(project_dir: &Path, kind: RunKind) -> String {
    format!(
        "suspense-sessions-{}-{}",
        project_key(project_dir),
        kind.conversation()
    )
}

/// The volume a project's Code runs keep their caches in.
pub fn cache_volume(project_dir: &Path) -> String {
    format!("suspense-cache-{}", project_key(project_dir))
}

/// Where, under its home, a harness keeps its sessions.
fn session_dir(agent: Agent) -> &'static str {
    match agent {
        let mut record = std::mem::take(&mut self.record);
        record.cancelled |= self.stopped.load(Ordering::SeqCst);
        // Off the UI thread: a long run's output can be large.
        std::thread::spawn(move || prompt_history::save_record(&file, &record).ok());
    }
}

/// A conversation with the harness, which later runs in the same project
/// resume so the harness keeps its context.
#[derive(Clone)]
struct Session {
    project_dir: PathBuf,
    /// Whether its runs ran in a container, whose volume keeps its sessions,
    /// rather than on the host; not known for one from the history.
    in_container: Option<bool>,
    id: String,
    /// How many tokens its context holds, as of its latest reply, once known.
    context: Option<u64>,
    /// The system prompt its latest run was sent, which a Freeform prompt
    /// carrying it on keeps, so the harness's cache holds; none when it was
    /// sent none, or its run wasn't recorded with one.
    system_prompt: Option<String>,
}

impl Session {
    /// The conversation to resume from `session`, if it is `project_dir`'s.
        if !self.in_background {
            let working = self.working;
            self.chat_input
                .update(cx, |input, cx| input.set_busy(working, cx));
        }

        // Whether it starts a new conversation is part of the prompt: a queued
        // one's anchor says, and one sent now is the first after New
        // conversation, if nothing else has been since.
        let new_conversation = match &sending {
            Sending::Queued(queued) => queued.anchor.new_conversation == Some(true),
            Sending::Now(..) => std::mem::take(self.new_conversation_pending.of_mut(lane)),
        };
        // A task whose mode runs in a container sees only what it may use,
        // as the ContainerEnvironmentScope says; Freeform runs on the host.
        let container_kind = (self.tasks[task_ix].mode != Some(SendMode::Freeform))
            .then(|| {
                crate::container::RunKind::of(
                    self.tasks[task_ix].mode,
                    crate::container::code_in_container(&project_dir),
                )
            })
            .flatten();
        // A conversation is only carried on where its sessions are kept: in
        // the lane's volume in a container, or on the host.
        let contained = container_kind.is_some();
        let resume = Session::resume(self.session.of(lane), &project_dir)
            .filter(|_| !new_conversation)
            .filter(|_| {
                self.session
                    .of(lane)
                    .as_ref()
                    .and_then(|session| session.in_container)
                    .is_none_or(|was| was == contained)
            });
        let new_conversation = resume.is_none();
        let epoch = *self.session_epoch.of(lane);
        let lsp = self.chat_input.read(cx).lsp();
        // A prompt that works on the code or the spec is sent against a
        // freshly built spec. A Freeform prompt is a task too, but is sent
        // just as it was typed: no build, compile, slices, system prompt, or
        // understanding file.
        let freeform = self.tasks[task_ix].mode == Some(SendMode::Freeform);
        let is_task = self.tasks[task_ix]
            .mode
            .is_none_or(|mode| mode != SendMode::Ask);
        let builds = is_task && !freeform;
        // What it may change, which a guard beside it keeps.
        let writes = self.tasks[task_ix].mode;
